function getRequestLanguage() {
  const locale = Now.getRequestLocale();
  return typeof locale === 'string' && locale.trim() !== '' ? locale.trim() : 'en';
}

function applyRequestLanguage(options = {}) {
  return Now.applyRequestLanguage(options);
}

/**
 * A modern, promise-based HTTP client for making API requests with security features.
 *
 * @class HttpClient
 * @description Provides a flexible and extensible way to make HTTP requests with support for
 * interceptors, CSRF protection, response handling, and more.
 *
 * @example
 *
 * const http = new HttpClient({
 *   baseURL: 'https://api.example.com'
 * });
 *
 *
 * const response = await http.get('/users');
 *
 *
 * const createResponse = await http.post('/users', { name: 'John Doe' });
 *
 * @example
 *
 * http.addRequestInterceptor(config => {
 *   config.headers['Authorization'] = `Bearer ${getToken()}`;
 *   return config;
 * });
 *
 * @property {string} baseURL - Base URL for all requests
 * @property {Object} defaultHeaders - Default headers sent with every request
 * @property {number} timeout - Request timeout in milliseconds
 * @property {Function} responseHandler - Custom response handler function
 * @property {Object} interceptors - Request and response interceptors
 * @property {boolean} throwOnError - Whether to throw errors on non-2xx responses
 * @property {string} csrfToken - CSRF token for request protection
 * @property {string} csrfHeaderName - Name of the CSRF header
 * @property {string} csrfCookieName - Name of the CSRF cookie
 * @property {string} csrfTokenSelector - CSS selector for the CSRF meta tag
 * @property {Object} security - Security configuration options
 */
class HttpClient {
  constructor(options = {}) {
    this.baseURL = options.baseURL || '';
    this.defaultHeaders = {
      'X-Requested-With': 'XMLHttpRequest',
      ...options.headers
    };
    this.timeout = options.timeout || 30000;
    this.responseHandler = options.responseHandler;
    this.interceptors = {
      request: [],
      response: []
    };

    this.throwOnError = options.throwOnError !== false;
    this.csrfToken = null;
    // Set once someone calls setCsrfToken(): the caller has taken over the
    // token, so SecurityManager's copy must not overwrite it.
    this.csrfTokenIsExplicit = false;

    this.security = options.security || {
      csrf: {
        enabled: false,
        required: true,
        tokenName: '_token',
        headerName: 'X-CSRF-Token'
      }
    };

    // Use CSRF config from security or use default.
    this.csrfHeaderName = this.security.csrf.headerName || 'X-CSRF-Token';
    this.csrfCookieName = options.csrfCookieName || 'XSRF-TOKEN';
    this.csrfTokenSelector = options.csrfTokenSelector || 'meta[name="csrf-token"]';

    // Always attempt to capture CSRF token so it's ready when needed
    this.setupCsrfToken();

    this.setupSecurity();
  }

  /**
   * Setup CSRF token from meta tag or cookie.
   * This method checks for a meta tag with the CSRF token or retrieves it from cookies.
   * If found, it sets the csrfToken property.
   */
  setupCsrfToken() {
    const metaToken = document.querySelector(this.csrfTokenSelector);
    if (metaToken) {
      this.csrfToken = metaToken.getAttribute('content');
      return;
    }

    const cookies = document.cookie.split(';');
    for (const cookie of cookies) {
      const [name, value] = cookie.trim().split('=');
      if (name === this.csrfCookieName) {
        this.csrfToken = decodeURIComponent(value);
        return;
      }
    }

    console.warn('CSRF token not found in meta tag or cookie');
  }

  /**
   * Setup security features like CSRF, rate limiting, and validation.
   * This method checks if SecurityManager is available and sets up interceptors accordingly.
   */
  setupSecurity() {
    this.addRequestInterceptor(async (config) => {
      try {
        return SecurityManager.addCSRFToRequest(config);
      } catch (error) {
        console.warn('CSRF interceptor error:', error);
        return config;
      }
    });



    // Request bodies are cleaned (when that is turned on) in one place only:
    // SecurityManager.prepareRequestBody, from its own interceptor
  }

  /**
   * Register an interceptor that runs before a request is sent.
   *
   * @param {Function} fn - Receives the config and returns the modified config.
   * @returns {Function} - A function that removes this interceptor.
   */
  addRequestInterceptor(fn) {
    this.interceptors.request.push(fn);
    return () => {
      const index = this.interceptors.request.indexOf(fn);
      if (index !== -1) this.interceptors.request.splice(index, 1);
    };
  }

  /**
   * Register an interceptor that runs once a response arrives.
   *
   * @param {Function} onFulfilled - Called when the request succeeds.
   * @param {Function} onRejected - Called when the request fails.
   * @returns {Function} - A function that removes this interceptor pair.
   */
  addResponseInterceptor(onFulfilled, onRejected) {
    this.interceptors.response.push({onFulfilled, onRejected});
    return () => {
      const index = this.interceptors.response.findIndex(i =>
        i.onFulfilled === onFulfilled && i.onRejected === onRejected);
      if (index !== -1) this.interceptors.response.splice(index, 1);
    };
  }

  /**
   * Run every request interceptor in registration order.
   *
   * Each result is passed to the next one, so config changes accumulate.
   *
   * @param {Object} config - The initial request config.
   * @returns {Promise<Object>} - The config after every interceptor has run.
   */
  async runRequestInterceptors(config) {
    let resultConfig = {...config};
    for (const interceptor of this.interceptors.request) {
      resultConfig = await interceptor(resultConfig);
    }
    return resultConfig;
  }

  /**
   * Run response interceptors after receiving a response.
   *
   * @param {Response} response - The fetch response object.
   * @param {boolean} [isError=false] - Whether this is an error response.
   * @returns {Promise<Object>} - The processed response object.
   */
  async runResponseInterceptors(response, isError = false) {
    let result = response;

    for (const interceptor of this.interceptors.response) {
      try {
        if (isError && interceptor.onRejected) {
          result = await interceptor.onRejected(result);
        } else if (!isError && interceptor.onFulfilled) {
          result = await interceptor.onFulfilled(result);
        } else if (!isError && !response.success && interceptor.onRejected) {
          result = await interceptor.onRejected(result);
        }
      } catch (error) {
        // An interceptor that throws is propagating the error onward, not failing:
        // `onRejected: error => { throw error; }` is the standard idiom, and
        // SecurityManager, ApiService and AuthManager all use it. Replacing the
        // result here would throw away the status and body the server actually
        // sent, so keep them and only note what the interceptor raised.
        const original = (result && typeof result === 'object') ? result : response;

        result = {
          success: false,
          status: 500,
          statusText: 'Interceptor Error',
          data: null,
          headers: {},
          ...original,
          error: original?.error ?? error
        };

        if (error !== original && error !== response) {
          result.interceptorError = error;
        }
        break;
      }
    }

    return result;
  }

  /**
   * Send a single request. Every method in this class routes through here.
   *
   * An AbortController is paired with the configured timeout, so a request that
   * hangs past the limit is aborted instead of waiting forever.
   * `options.timeout` (ms) overrides the client's timeout for this one request,
   * and 0 removes the limit — for calls that legitimately run long, such as AI
   * generation, without raising the timeout of every other request.
   *
   * @param {string} url - The target URL.
   * @param {Object} [options={}] - Fetch options, plus method, body and timeout.
   * @returns {Promise<Object>} - The processed response.
   */
  async request(url, options = {}) {
    const controller = new AbortController();
    let timeoutId;
    const timeout = options.timeout !== undefined && options.timeout !== null ? Number(options.timeout) : this.timeout;

    if (timeout) {
      timeoutId = setTimeout(() => controller.abort(), timeout);
    }

    try {
      const baseUrl = /^(https?:)?\/\//.test(url) ? url : `${this.baseURL}${url}`;
      const finalUrl = this.appendQueryParams(baseUrl, options.params);

      let config = applyRequestLanguage({
        method: options.method || 'GET',
        ...options,
        headers: {
          ...this.defaultHeaders,
          ...options.headers
        },
        signal: controller.signal,
        credentials: options.credentials || 'same-origin'
      });
      // Interceptors decide by the destination (credentials go to trusted origins only)
      config.url = finalUrl;
      // Work on a copy: a token or cleaning must never change the caller's object
      config.body = copyRequestBody(config.body);

      delete config.params;
      delete config.timeout;

      config = await this.runRequestInterceptors(config);
      config = this.ensureCsrf(config);
      config.body = this.processRequestBody(config);
      config = this.normalizeRequestOptions(config);
      delete config.url;

      const response = await fetch(finalUrl, config);
      clearTimeout(timeoutId);

      // Update CSRF token from response headers (before custom handler may process)
      const newCsrfToken = isTrustedRequestUrl(response.url || finalUrl) ? response.headers.get(this.csrfHeaderName) : null;
      if (newCsrfToken) {
        this.csrfToken = newCsrfToken;
      }

      let result;
      if (this.responseHandler) {
        result = await this.responseHandler(response);
      } else {
        result = await this.handleResponse(response);
      }

      return await this.runResponseInterceptors(result);

    } catch (error) {
      clearTimeout(timeoutId);

      const errorResponse = {
        success: false,
        status: error.name === 'AbortError' ? 408 : (error.status || 500),
        statusText: error.name === 'AbortError' ? 'Request timeout' : (error.message || 'Unknown error'),
        data: null,
        headers: {},
        error: error,
        url: url
      };

      try {
        const processedError = await this.runResponseInterceptors(errorResponse, true);
        return processedError;
      } catch (interceptorError) {
        return errorResponse;
      }
    }
  }

  /**
   * Append a query string to a URL.
   *
   * @param {string} url - The base URL.
   * @param {Object} params - Parameters to append.
   * @returns {string} - The URL with the query string appended.
   */
  appendQueryParams(url, params) {
    if (!params) {
      return url;
    }

    const searchParams = new URLSearchParams();
    const appendValue = (key, value) => {
      if (value === undefined || value === null) {
        return;
      }

      if (Array.isArray(value)) {
        value.forEach(item => appendValue(key, item));
        return;
      }

      if (value instanceof Date) {
        searchParams.append(key, value.toISOString());
        return;
      }

      if (typeof value === 'object') {
        searchParams.append(key, JSON.stringify(value));
        return;
      }

      searchParams.append(key, String(value));
    };

    if (params instanceof URLSearchParams) {
      params.forEach((value, key) => appendValue(key, value));
    } else if (typeof params === 'object') {
      Object.entries(params).forEach(([key, value]) => appendValue(key, value));
    } else {
      return url;
    }

    const queryString = searchParams.toString();
    if (!queryString) {
      return url;
    }

    return `${url}${url.includes('?') ? '&' : '?'}${queryString}`;
  }

  /**
   * Prepare the body for sending and set Content-Type to match its type.
   *
   * Content-Type is dropped for FormData, URLSearchParams, Blob and ArrayBuffer
   * so the browser can fill in the correct boundary itself.
   *
   * @param {Object} config - The request config.
   * @returns {*} - The body ready to send, or null when there is none.
   */
  processRequestBody(config) {
    const {body, headers} = config;
    if (!body) return null;

    if (body instanceof FormData || body instanceof URLSearchParams ||
      body instanceof Blob || body instanceof ArrayBuffer) {
      delete headers['Content-Type'];
      return body;
    }

    if (typeof body === 'object') {
      if (!headers['Content-Type']) {
        headers['Content-Type'] = 'application/json';
      }
      if (headers['Content-Type']?.includes('application/json')) {
        return JSON.stringify(body);
      }
    }

    return body;
  }

  /**
   * Normalize the options before sending.
   *
   * A JSON Content-Type is dropped when the request has no body, to avoid caches
   * and CDNs that reject a GET carrying a Content-Type.
   *
   * @param {Object} options - The initial options.
   * @returns {Object} - The normalized options.
   */
  normalizeRequestOptions(options) {
    const result = {...options};

    // Remove JSON content-type for requests without body to avoid cache/CDN issues
    if (!result.body && result.headers?.['Content-Type'] === 'application/json') {
      delete result.headers['Content-Type'];
    }

    if (result.cache === true) {
      result.cache = 'default';
    } else if (result.cache === false) {
      result.cache = 'no-store';
    }

    return result;
  }

  /**
   * Check for a CSRF token before sending a state-changing request.
   *
   * Only POST, PUT, PATCH and DELETE are checked, and only while CSRF is
   * enabled and `security.csrf.required` is on, so a GET goes through without
   * a token.
   *
   * The token is looked up again here rather than trusting the single read the
   * constructor does: SecurityManager fetches the token over the network and
   * writes the meta tag long after this client is built, so at construction
   * time the page usually carries nothing yet.
   *
   * @param {Object} config - The request config.
   * @returns {Object} - The config, with the token attached when there is one.
   * @throws {HttpError} - Status 400 when a required token is missing.
   */
  ensureCsrf(config) {
    const method = (config.method || 'GET').toUpperCase();
    const stateChanging = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(method);

    // A request that opted out (FormManager sets this for data-csrf="false")
    // must go through untouched, token or no token.
    if (config.headers?.['X-Skip-CSRF'] === 'true') {
      return config;
    }

    // The token is ours: it goes only to this origin (or a trusted one), and only
    // with a request that changes state — GET/HEAD/OPTIONS never carry it
    if (!stateChanging || !isTrustedRequestUrl(config.url)) {
      return config;
    }

    // SecurityManager owns the token while it is running; its state stays in
    // sync with the refresh timer and the response headers, so prefer it and
    // fall back to the meta tag or the cookie.
    const managedToken = this.csrfTokenIsExplicit ? null : window.SecurityManager?.state?.csrfToken;
    if (managedToken) {
      this.csrfToken = managedToken;
    } else if (!this.csrfToken) {
      this.csrfToken = getCsrfToken(this.csrfCookieName, this.csrfTokenSelector);
    }

    // `required` only bites while CSRF protection is actually on. The default
    // config pairs required: true with enabled: false, which would otherwise
    // block every POST in an application that never turned CSRF on.
    const csrfEnabled = this.security.csrf.enabled === true ||
      window.SecurityManager?.config?.csrf?.enabled === true;

    if (!this.csrfToken && csrfEnabled && this.security.csrf.required && stateChanging) {
      throw new HttpError('Missing CSRF token', 400);
    }

    if (this.csrfToken) {
      config.headers = config.headers || {};
      config.headers[this.csrfHeaderName] = this.csrfToken;

      // config.body is already a copy of the caller's (request() makes it)
      const body = config.body;
      const tokenName = this.security.csrf.tokenName || '_token';
      if (typeof body === 'object' && body !== null && Object.getPrototypeOf(body) === Object.prototype && !body[tokenName]) {
        body[tokenName] = this.csrfToken;
      } else if (body instanceof FormData && !body.has(tokenName)) {
        body.append(tokenName, this.csrfToken);
      }
    }

    return config;
  }

  /**
   * Turn the raw response into a usable shape and pick up a fresh CSRF token.
   *
   * A token returned in the headers immediately replaces the stored one, so the
   * next request uses the latest one without the caller doing anything.
   *
   * @param {Response} response - The response from fetch.
   * @returns {Promise<Object>} - The result parsed according to its content-type.
   */
  async handleResponse(response) {
    const newCsrfToken = isTrustedRequestUrl(response.url) ? response.headers.get(this.csrfHeaderName) : null;
    if (newCsrfToken) {
      this.csrfToken = newCsrfToken;
    }

    const contentType = response.headers.get('content-type');
    const isJSON = contentType?.includes('application/json');
    const isText = contentType?.includes('text/');
    const isBlob = contentType?.includes('application/octet-stream');

    let data;
    try {
      if (isJSON) {
        data = await response.json();
      } else if (isBlob) {
        data = await response.blob();
      } else if (isText) {
        data = await response.text();
      } else {
        data = response;
      }
    } catch (parseError) {
      data = await response.text();
    }

    const result = {
      success: response.ok,  // HTTP success mapped to success
      status: response.status,
      statusText: response.statusText,
      data: data,
      headers: this.getHeadersObject(response),
      url: response.url
    };

    return result;
  }

  /**
   * Convert the response Headers into a plain object.
   *
   * @param {Response} response - The response from fetch.
   * @returns {Object} - The headers as key-value pairs.
   */
  getHeadersObject(response) {
    const headers = {};
    response.headers.forEach((value, key) => {
      headers[key] = value;
    });
    return headers;
  }

  /**
   * Build an HttpError from a response with an unsuccessful status.
   *
   * @param {Object} response - The failed response.
   * @returns {HttpError} - The error, ready to throw.
   */
  createHttpError(response) {
    return new HttpError(
      response.statusText || 'HTTP Error',
      response.status,
      response
    );
  }

  /**
   * Convert an error raised while sending the request into an HttpError.
   *
   * `AbortError` is read as a timeout and gets status 408; anything else keeps the
   * status carried on the error, or 500 when it has none.
   *
   * @param {Error} error - The caught error.
   * @returns {HttpError} - The converted error.
   */
  createErrorResponse(error) {
    const isTimeout = error.name === 'AbortError';
    const status = isTimeout ? 408 : error.status || 500;
    const message = isTimeout ? 'Request timeout' : error.message || 'Unknown error';

    return new HttpError(message, status, error.response);
  }

  /**
   * Pick the most useful message for a failed response.
   *
   * The API's own `message` says what went wrong; `statusText` only repeats the
   * status line, so it is the last resort.
   *
   * @param {Object} response - The processed response.
   * @returns {string} - The message to report.
   */
  getErrorMessage(response) {
    const data = response?.data;

    if (data && typeof data === 'object') {
      if (typeof data.message === 'string' && data.message.trim() !== '') {
        return data.message;
      }
      if (typeof data.error === 'string' && data.error.trim() !== '') {
        return data.error;
      }
    }

    if (typeof data === 'string' && data.trim() !== '' && data.length <= 200) {
      return data;
    }

    return response?.statusText || 'HTTP Error';
  }

  async get(url, options = {}) {
    const response = await this.request(url, {...options, method: 'GET'});

    if (options.throwOnError !== false && this.throwOnError && !response.success) {
      throw new HttpError(this.getErrorMessage(response), response.status, response);
    }

    return response;
  }

  async post(url, data, options = {}) {
    const response = await this.request(url, {...options, method: 'POST', body: data});

    if (options.throwOnError !== false && this.throwOnError && !response.success) {
      throw new HttpError(this.getErrorMessage(response), response.status, response);
    }

    return response;
  }

  async put(url, data, options = {}) {
    const response = await this.request(url, {...options, method: 'PUT', body: data});

    if (options.throwOnError !== false && this.throwOnError && !response.success) {
      throw new HttpError(this.getErrorMessage(response), response.status, response);
    }

    return response;
  }

  async delete(url, options = {}) {
    const response = await this.request(url, {...options, method: 'DELETE'});

    if (options.throwOnError !== false && this.throwOnError && !response.success) {
      throw new HttpError(this.getErrorMessage(response), response.status, response);
    }

    return response;
  }

  patch(url, data, options = {}) {
    return this.request(url, {...options, method: 'PATCH', body: data});
  }

  /**
   * Send a HEAD request.
   *
   * @param {string} url - The target URL.
   * @param {Object} [options={}] - Extra options.
   * @returns {Promise<Object>} - response
   */
  head(url, options = {}) {
    return this.request(url, {...options, method: 'HEAD'});
  }

  /**
   * Send an OPTIONS request.
   *
   * @param {string} url - The target URL.
   * @param {Object} [options={}] - Extra options.
   * @returns {Promise<Object>} - response
   */
  options(url, options = {}) {
    return this.request(url, {...options, method: 'OPTIONS'});
  }

  upload(url, files, options = {}) {
    const formData = new FormData();

    if (Array.isArray(files)) {
      files.forEach((file, i) => formData.append(`file${i}`, file));
    } else {
      formData.append('file', files);
    }

    if (options.data) {
      Object.entries(options.data).forEach(([key, value]) => {
        formData.append(key, value);
      });
    }

    return this.request(url, {
      ...options,
      method: 'POST',
      body: formData
    });
  }

  /**
   * A GET that never throws, whatever the status.
   *
   * Unlike `get()` it ignores `throwOnError` entirely, so the caller must read
   * `response.success` itself. Useful where a 404 is a normal result, not an error.
   *
   * @param {string} url - The target URL.
   * @param {Object} [options={}] - Extra options.
   * @returns {Promise<Object>} - The raw response; never throws on a failed status.
   */
  async getSafe(url, options = {}) {
    return this.request(url, {...options, method: 'GET'});
  }

  /**
   * A POST that never throws, whatever the status.
   *
   * @param {string} url - The target URL.
   * @param {*} data - The data to send.
   * @param {Object} [options={}] - Extra options.
   * @returns {Promise<Object>} - The raw response; never throws on a failed status.
   */
  async postSafe(url, data, options = {}) {
    return this.request(url, {...options, method: 'POST', body: data});
  }

  /**
   * A PUT that never throws, whatever the status.
   *
   * @param {string} url - The target URL.
   * @param {*} data - The data to send.
   * @param {Object} [options={}] - Extra options.
   * @returns {Promise<Object>} - The raw response; never throws on a failed status.
   */
  async putSafe(url, data, options = {}) {
    return this.request(url, {...options, method: 'PUT', body: data});
  }

  /**
   * A DELETE that never throws, whatever the status.
   *
   * @param {string} url - The target URL.
   * @param {Object} [options={}] - Extra options.
   * @returns {Promise<Object>} - The raw response; never throws on a failed status.
   */
  async deleteSafe(url, options = {}) {
    return this.request(url, {...options, method: 'DELETE'});
  }

  setBaseURL(url) {
    this.baseURL = url;
  }

  /**
   * Set one default header that goes out with every request.
   *
   * @param {string} name - The header name.
   * @param {string} value - The value.
   * @returns {void}
   */
  setDefaultHeader(name, value) {
    this.defaultHeaders[name] = value;
  }

  /**
   * Merge several default headers into the existing set.
   *
   * This merges rather than replaces, so headers not named here survive.
   *
   * @param {Object} headers - The headers to merge in.
   * @returns {void}
   */
  setDefaultHeaders(headers) {
    this.defaultHeaders = {
      ...this.defaultHeaders,
      ...headers
    };
  }

  setTimeout(timeout) {
    this.timeout = timeout;
  }

  /**
   * Set the CSRF token attached to state-changing requests.
   *
   * The token set here wins over the one SecurityManager holds, so a caller
   * that manages its own tokens keeps them.
   *
   * @param {string} token - The new token.
   * @returns {void}
   */
  setCsrfToken(token) {
    this.csrfToken = token;
    this.csrfTokenIsExplicit = true;
  }
}

class HttpError extends Error {
  constructor(message, status, response = null) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
    this.response = response;
    this.timestamp = Date.now();
  }
}

const http = new HttpClient({
  throwOnError: false,
  responseHandler: async (response) => {
    const contentType = response.headers.get('content-type');
    let data;

    try {
      if (contentType?.includes('application/json')) {
        data = await response.json();
      } else if (contentType?.includes('text/')) {
        data = await response.text();
      } else if (contentType?.includes('application/octet-stream')) {
        data = await response.blob();
      } else {
        data = await response.text();
      }
    } catch (e) {
      data = null;
    }

    return {
      success: response.ok,
      status: response.status,
      statusText: response.statusText,
      data,
      headers: Object.fromEntries(response.headers.entries()),
      url: response.url,
      timestamp: Date.now(),
      requestId: response.headers.get('X-Request-ID')
    };
  }
});

const httpThrow = new HttpClient({
  throwOnError: true,
  responseHandler: async (response) => {
    const contentType = response.headers.get('content-type');
    let data;

    if (contentType?.includes('application/json')) {
      data = await response.json();
    } else if (contentType?.includes('text/')) {
      data = await response.text();
    } else if (contentType?.includes('application/octet-stream')) {
      data = await response.blob();
    } else {
      data = await response.text();
    }

    const result = {
      status: response.status,
      data,
      message: data?.message || response.statusText,
      meta: data?.meta,
      timestamp: Date.now(),
      headers: Object.fromEntries(response.headers.entries()),
      requestId: response.headers.get('X-Request-ID')
    };

    if (!response.ok) {
      throw new HttpError(
        result.message || 'Server Error',
        result.status,
        result
      );
    }

    return result;
  }
});

/**
 * SimpleFetch - A lightweight fetch wrapper for easy HTTP requests
 * Zero dependencies, auto-parsing, and convenient methods
 *
 * @example
 * // Get JSON data directly
 * const users = await simpleFetch.json('/api/users');
 *
 * // Post data easily
 * const result = await simpleFetch.post('/api/users', {name: 'John'});
 *
 * // Get full response object
 * const response = await simpleFetch('/api/users');
 * console.log(response.data, response.success, response.status);
 */
const simpleFetch = {
  // Configuration
  config: {
    baseURL: '',
    defaultHeaders: {
      'X-Requested-With': 'XMLHttpRequest'
    },
    timeout: 15000
  },

  /**
   * Core fetch method with auto-parsing and consistent response format
   */
  async fetch(url, options = {}) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.config.timeout);

    try {
      // Build final URL
      const finalUrl = /^(https?:)?\/\//.test(url) ? url : `${this.config.baseURL}${url}`;

      // Prepare request config
      const config = applyRequestLanguage({
        method: 'GET',
        headers: {
          ...this.config.defaultHeaders
        },
        credentials: 'same-origin',
        signal: controller.signal,
        ...options
      });

      // Merge headers
      if (options.headers) {
        config.headers = {...config.headers, ...options.headers};
      }

      // Work on a copy: the token must never change the caller's object
      config.body = copyRequestBody(config.body);

      // CSRF support (share logic with HttpClient defaults): state-changing
      // requests to this origin (or a trusted one) only
      const stateChanging = ['POST', 'PUT', 'PATCH', 'DELETE'].includes((config.method || 'GET').toUpperCase());
      const csrfToken = stateChanging && isTrustedRequestUrl(finalUrl)
        ? getCsrfToken(this.config.csrfCookieName || 'XSRF-TOKEN', this.config.csrfSelector || 'meta[name="csrf-token"]')
        : null;
      if (csrfToken) {
        // Header names are case-insensitive to the browser: a caller-supplied
        // 'X-CSRF-TOKEN' next to our 'X-CSRF-Token' is sent as one header
        // "tok, tok", which the server rejects as a malformed token (419).
        const csrfHeaderName = this.config.csrfHeaderName || 'X-CSRF-Token';
        for (const name of Object.keys(config.headers)) {
          if (name !== csrfHeaderName && name.toLowerCase() === csrfHeaderName.toLowerCase()) {
            delete config.headers[name];
          }
        }
        config.headers[csrfHeaderName] = csrfToken;
        if (config.body instanceof FormData) {
          if (!config.body.has('_token')) config.body.append('_token', csrfToken);
        } else if (config.body && typeof config.body === 'object' && Object.getPrototypeOf(config.body) === Object.prototype) {
          if (!config.body._token) config.body._token = csrfToken;
        }
      }

      // Auth token is sent automatically as the server-set httpOnly `auth_token`
      // cookie (credentials default to 'same-origin'). The token is intentionally
      // never read from JS storage — it must remain inaccessible to JavaScript.

      // Handle body
      if (config.body && typeof config.body === 'object' && !(config.body instanceof FormData)) {
        config.headers['Content-Type'] = config.headers['Content-Type'] || 'application/json';
        if (config.headers['Content-Type'].includes('application/json')) {
          config.body = JSON.stringify(config.body);
        }
      }

      if (config.headers && (config.headers['Content-Type'] === undefined || config.headers['Content-Type'] === null)) {
        delete config.headers['Content-Type'];
      }

      if (!config.body && config.headers) {
        delete config.headers['Content-Type'];
      }

      if (config.body instanceof FormData && config.headers) {
        delete config.headers['Content-Type'];
      }

      // Make request
      const response = await fetch(finalUrl, config);
      clearTimeout(timeoutId);

      // The server rotates the CSRF token on every response. simpleFetch bypasses
      // the http interceptors, so adopt the rotated token here or the meta tag
      // goes stale (a new PHP session after idle/GC) and every later POST gets 419.
      if (isTrustedRequestUrl(response.url || finalUrl)) {
        adoptCsrfToken(response.headers.get(this.config.csrfHeaderName || 'X-CSRF-Token'), this.config.csrfSelector || 'meta[name="csrf-token"]');
      }

      // Auto-parse response
      const contentType = response.headers.get('content-type') || '';
      let data;

      try {
        if (contentType.includes('application/json')) {
          data = await response.json();
        } else if (contentType.includes('text/')) {
          data = await response.text();
        } else if (contentType.includes('application/octet-stream') || contentType.includes('application/pdf')) {
          data = await response.blob();
        } else {
          // Try JSON first, fallback to text
          const text = await response.text();
          try {
            data = JSON.parse(text);
          } catch {
            data = text;
          }
        }
      } catch (parseError) {
        data = null;
      }

      return {
        success: response.ok,
        status: response.status,
        statusText: response.statusText,
        data,
        headers: Object.fromEntries(response.headers.entries()),
        url: response.url
      };

    } catch (error) {
      clearTimeout(timeoutId);

      return {
        success: false,
        status: error.name === 'AbortError' ? 408 : 0,
        statusText: error.name === 'AbortError' ? 'Request Timeout' : error.message,
        data: null,
        headers: {},
        url: url,
        error: error
      };
    }
  },

  /**
   * GET request - returns full response object
   */
  async get(url, options = {}) {
    return this.fetch(url, {...options, method: 'GET'});
  },

  /**
   * POST request - returns full response object
   */
  async post(url, data = null, options = {}) {
    return this.fetch(url, {
      ...options,
      method: 'POST',
      body: data
    });
  },

  /**
   * PUT request - returns full response object
   */
  async put(url, data = null, options = {}) {
    return this.fetch(url, {
      ...options,
      method: 'PUT',
      body: data
    });
  },

  /**
   * DELETE request - returns full response object
   */
  async delete(url, options = {}) {
    return this.fetch(url, {...options, method: 'DELETE'});
  },

  /**
   * PATCH request - returns full response object
   */
  async patch(url, data = null, options = {}) {
    return this.fetch(url, {
      ...options,
      method: 'PATCH',
      body: data
    });
  },

  // ========== CONVENIENCE METHODS (return data directly) ==========

  /**
   * GET request - returns parsed JSON data directly
   * @param {string} url - Request URL
   * @param {object} options - Fetch options
   * @returns {Promise<any>} Parsed data or null on error
   */
  async json(url, options = {}) {
    const response = await this.get(url, options);
    return response.success ? response.data : null;
  },

  /**
   * GET request - returns text data directly
   * @param {string} url - Request URL
   * @param {object} options - Fetch options
   * @returns {Promise<string>} Text data or null on error
   */
  async text(url, options = {}) {
    const response = await this.get(url, options);
    return response.success ? response.data : null;
  },

  /**
   * POST JSON data - returns data directly
   * @param {string} url - Request URL
   * @param {object} data - Data to send
   * @param {object} options - Fetch options
   * @returns {Promise<any>} Response data or null on error
   */
  async postJson(url, data, options = {}) {
    const response = await this.post(url, data, options);
    return response.success ? response.data : null;
  },

  /**
   * Upload files using FormData
   * @param {string} url - Upload URL
   * @param {File|File[]|FormData} files - Files to upload
   * @param {object} data - Additional form data
   * @param {object} options - Fetch options
   * @returns {Promise<object>} Response object
   */
  async upload(url, files, data = {}, options = {}) {
    let formData;

    if (files instanceof FormData) {
      formData = files;
    } else {
      formData = new FormData();

      if (Array.isArray(files)) {
        files.forEach((file, index) => {
          formData.append(`file${index}`, file);
        });
      } else if (files) {
        formData.append('file', files);
      }
    }

    // Add additional data
    Object.entries(data).forEach(([key, value]) => {
      formData.append(key, value);
    });

    // Remove content-type header to let browser set it with boundary
    const headers = {...options.headers};
    delete headers['Content-Type'];

    return this.post(url, formData, {...options, headers});
  },

  // ========== CONFIGURATION METHODS ==========

  /**
   * Set base URL for all requests
   * @param {string} url - Base URL
   */
  setBaseURL(url) {
    this.config.baseURL = url.endsWith('/') ? url.slice(0, -1) : url;
    return this;
  },

  /**
   * Set default headers
   * @param {object} headers - Headers object
   */
  setHeaders(headers) {
    this.config.defaultHeaders = {...this.config.defaultHeaders, ...headers};
    return this;
  },

  /**
   * Set single header
   * @param {string} name - Header name
   * @param {string} value - Header value
   */
  setHeader(name, value) {
    this.config.defaultHeaders[name] = value;
    return this;
  },

  /**
   * Set request timeout
   * @param {number} timeout - Timeout in milliseconds
   */
  setTimeout(timeout) {
    this.config.timeout = timeout;
    return this;
  },

  /**
   * Remove a default header
   * @param {string} name - Header name to remove
   */
  removeHeader(name) {
    delete this.config.defaultHeaders[name];
    return this;
  },

  /**
   * Reset configuration to defaults
   */
  resetConfig() {
    this.config = {
      baseURL: '',
      defaultHeaders: {
        'Content-Type': 'application/json',
        'X-Requested-With': 'XMLHttpRequest'
      },
      timeout: 15000
    };
    return this;
  }
};

/**
 * httpAction - HTTP client that automatically processes responses through ResponseHandler.
 *
 * Combines `window.http` with `ResponseHandler.process()` so the caller gets the full
 * response object back AND all server-driven actions (notifications, redirects, modals, etc.)
 * are executed automatically — without needing manual ResponseHandler calls.
 *
 * @example
 * // Post an action and let ResponseHandler handle notifications/redirects automatically
 * const response = await httpAction.post(`${WEB_URL}api/board/action`, {
 *   module_id: moduleId,
 *   action: 'delete',
 *   id: id
 * });
 * if (response.success) { ... }
 *
 * @example
 * // Pass extra context to ResponseHandler (e.g. for modal or reload callbacks)
 * const response = await httpAction.get(url, {}, { reload: () => loadData() });
 */
const httpAction = {
  /**
   * Reshape query options into the form httpAction expects.
   *
   * Returns the input untouched when it is not an object, or already has `params`.
   *
   * @param {Object} [options={}] - The initial options.
   * @returns {Object} - The normalized options.
   */
  normalizeQueryOptions(options = {}) {
    if (!options || typeof options !== 'object' || Array.isArray(options)) {
      return options;
    }

    if (options.params !== undefined) {
      return options;
    }

    const fetchOptionKeys = new Set([
      'method',
      'headers',
      'body',
      'credentials',
      'signal',
      'cache',
      'redirect',
      'mode',
      'referrer',
      'referrerPolicy',
      'integrity',
      'keepalive',
      'priority',
      'throwOnError'
    ]);

    const optionKeys = Object.keys(options);
    const looksLikeFetchOptions = optionKeys.some(key => fetchOptionKeys.has(key));

    if (looksLikeFetchOptions) {
      return options;
    }

    return {
      params: options
    };
  },

  /**
   * Internal dispatcher: runs http[method], then ResponseHandler.process() on the result.
   * @param {string} method - HTTP method name on window.http
   * @param {Array} args - Arguments forwarded to http[method]
   * @param {object} [context={}] - Extra context forwarded to ResponseHandler.process()
   * @returns {Promise<object>} The full response object from HttpClient
   */
  async _dispatch(method, args, context = {}) {
    const response = await window.http[method](...args);

    // ResponseHandler.process() expects the inner `data` payload, not the outer HttpClient wrapper.
    // The inner payload is response.data when the server returns JSON, otherwise skip processing.
    if (window.ResponseHandler && response) {
      await window.ResponseHandler.process(this.responsePayload(response), context);
    }

    return response;
  },

  /**
   * Pick the level of the response that actually carries `actions`.
   * @param {object} response - Full HttpClient wrapper
   * @returns {*} Payload for ResponseHandler.process()
   * @private
   */
  responsePayload(response) {
    return window.ResponseHandler.payloadOf(response);
  },

  /**
   * GET request with automatic ResponseHandler processing.
   * @param {string} url
   * @param {object} [options={}]
   * @param {object} [context={}]
   * @returns {Promise<object>}
   */
  async get(url, options = {}, context = {}) {
    return this._dispatch('get', [url, this.normalizeQueryOptions(options)], context);
  },

  /**
   * POST request with automatic ResponseHandler processing.
   * @param {string} url
   * @param {*} data
   * @param {object} [options={}]
   * @param {object} [context={}]
   * @returns {Promise<object>}
   */
  async post(url, data, options = {}, context = {}) {
    return this._dispatch('post', [url, data, options], context);
  },

  /**
   * PUT request with automatic ResponseHandler processing.
   * @param {string} url
   * @param {*} data
   * @param {object} [options={}]
   * @param {object} [context={}]
   * @returns {Promise<object>}
   */
  async put(url, data, options = {}, context = {}) {
    return this._dispatch('put', [url, data, options], context);
  },

  /**
   * PATCH request with automatic ResponseHandler processing.
   * @param {string} url
   * @param {*} data
   * @param {object} [options={}]
   * @param {object} [context={}]
   * @returns {Promise<object>}
   */
  async patch(url, data, options = {}, context = {}) {
    return this._dispatch('patch', [url, data, options], context);
  },

  /**
   * DELETE request with automatic ResponseHandler processing.
   * @param {string} url
   * @param {object} [options={}]
   * @param {object} [context={}]
   * @returns {Promise<object>}
   */
  async delete(url, options = {}, context = {}) {
    return this._dispatch('delete', [url, this.normalizeQueryOptions(options)], context);
  },

  /**
   * File upload with automatic ResponseHandler processing.
   * @param {string} url
   * @param {File|File[]|FormData} files
   * @param {object} [options={}]
   * @param {object} [context={}]
   * @returns {Promise<object>}
   */
  async upload(url, files, options = {}, context = {}) {
    return this._dispatch('upload', [url, files, options], context);
  }
};

/**
 * Adopt a CSRF token rotated by the server: SecurityManager owns the token
 * while it runs (its state feeds every http request), so update it there and
 * let it propagate to the meta tag and forms; otherwise write the meta tag.
 *
 * @param {string|null} token - Token from the response header, if any
 * @param {string} [selector] - CSS selector of the CSRF meta tag
 * @returns {void}
 */
function adoptCsrfToken(token, selector = 'meta[name="csrf-token"]') {
  if (!token) return;

  try {
    const sm = window.SecurityManager;
    if (sm?.state && typeof sm.updateCSRFMeta === 'function') {
      if (sm.state.csrfToken === token) return;
      sm.state.csrfToken = token;
      sm.updateCSRFMeta(token);
      if (typeof sm.updateCSRFInForms === 'function') sm.updateCSRFInForms(token);
      return;
    }

    let meta = document.querySelector(selector);
    if (!meta) {
      meta = document.createElement('meta');
      meta.name = 'csrf-token';
      document.head.appendChild(meta);
    }
    meta.setAttribute('content', token);
  } catch (e) {
    console.warn('Failed to adopt rotated CSRF token', e);
  }
}

/**
 * Whether a request to `url` may carry this app's credentials and hand back a
 * new CSRF token: SecurityManager.isTrustedOrigin() (this origin or one in
 * SecurityManager.config.trustedOrigins), or this origin when SecurityManager
 * is not loaded.
 *
 * @param {string} [url] - Request URL
 * @returns {boolean}
 */
function isTrustedRequestUrl(url) {
  if (window.SecurityManager && typeof window.SecurityManager.isTrustedOrigin === 'function') {
    return window.SecurityManager.isTrustedOrigin(url);
  }
  if (url === undefined || url === null || url === '') return true;
  try {
    return new URL(String(url), window.location.href).origin === window.location.origin;
  } catch (e) {
    return false;
  }
}

/**
 * A copy of a request body that can be changed without touching the caller's:
 * a plain object is copied one level deep, FormData entry by entry; anything
 * else (string, Blob, URLSearchParams, …) is returned as it is.
 *
 * @param {*} body - Request body
 * @returns {*} The copy
 */
function copyRequestBody(body) {
  if (body instanceof FormData) {
    const copy = new FormData();
    for (const [key, value] of body) {
      if (typeof value === 'string') copy.append(key, value);
      else copy.append(key, value, value.name);
    }
    return copy;
  }
  if (body && typeof body === 'object' && Object.getPrototypeOf(body) === Object.prototype) {
    return {...body};
  }
  return body;
}

function getCsrfToken(cookieName = 'XSRF-TOKEN', selector = 'meta[name="csrf-token"]') {
  const metaToken = document.querySelector(selector);
  if (metaToken) return metaToken.getAttribute('content');

  const cookies = document.cookie.split(';');
  for (const cookie of cookies) {
    const [name, value] = cookie.trim().split('=');
    if (name === cookieName) return decodeURIComponent(value);
  }
  return null;
}

window.HttpClient = HttpClient;
window.http = http;
window.httpThrow = httpThrow;
window.simpleFetch = simpleFetch;
window.httpAction = httpAction;